export const PRIMARY_STAGE_IDS = Object.freeze(["stage-1", "stage-2", "stage-3"]);

export const BEYOND_PRIMARY_STAGE_ID = "beyond-primary";

const primaryStageIds = [...PRIMARY_STAGE_IDS];

const EVIDENCE_LEVEL_LABELS = {"direct":"Direct","conceptual":"Conceptual","adjacent":"Adjacent","not-covered":"Not-covered"};

const evidenceLabels = EVIDENCE_LEVEL_LABELS;

function assert(condition,message){if(!condition)throw new Error(message);}

function sameSet(left,right){const a=new Set(left),b=new Set(right);return a.size===left.length&&b.size===right.length&&a.size===b.size&&[...a].every(value=>b.has(value));}

function uniqueList(values,label){const list=Array.isArray(values)?values:[];assert(new Set(list).size===list.length,"Duplicate IDs in "+label);return list;}

function normalizeStageJudgement(raw,stageId){const source=raw&&typeof raw==="object"?raw:{};const required=["mark","markLabel","reviewStatus"];const missingFields=required.filter(key=>typeof source[key]!=="string");return {...source,stageId,recordStatus:missingFields.length===0?"complete":"incomplete",mark:typeof source.mark==="string"?source.mark:null,markLabel:typeof source.markLabel==="string"?source.markLabel:null,reviewStatus:typeof source.reviewStatus==="string"?source.reviewStatus:null,sourceFieldsPresent:Object.keys(source).sort(),missingFields};}

