 const notCoveredIds=uniqueList((specialRisks.notCoveredNodes??[]).map(item=>item.id),"not-covered risk IDs"),actualNotCoveredIds=nodeMappings.filter(item=>item.curriculum.evidenceLevel==="not-covered").map(item=>item.nodeId);assert(sameSet(notCoveredIds,actualNotCoveredIds),"Not-covered risk list differs from node mapping evidence");const adjacentMainIds=uniqueList((specialRisks.adjacentMain?.nodes??[]).map(item=>item.id),"Adjacent/Main risk IDs"),actualAdjacentMainIds=nodeMappings.filter(item=>item.curriculum.evidenceLevel==="adjacent"&&Object.values(item.curriculum.roles).includes("main")).map(item=>item.nodeId);assert(sameSet(adjacentMainIds,actualAdjacentMainIds),"Adjacent/Main risk list differs from node mapping evidence");assert(specialRisks.adjacentMain?.count===adjacentMainIds.length,"Adjacent/Main risk count mismatch");
 const unresolved=specialRisks.unresolvedNode,unresolvedMapping=mappedById.get(unresolved?.id);assert(unresolvedMapping&&unresolvedMapping.curriculum.beyondPrimary?.role===unresolved.role&&unresolvedMapping.curriculum.evidenceLevel==="adjacent","Unresolved node state does not match node mapping");const atlasPackMemberIds=atlasPacks.flatMap(pack=>pack.nodeIds);assert(atlasPackMemberIds.length===atlasNodes.length&&sameSet(atlasPackMemberIds,atlasNodes.map(node=>node.id)),"Atlas pack membership is incomplete or duplicated");
 const incompletePackStages=[];for(const pack of packRecords)for(const stageId of primaryIds){const judgement=pack.stageJudgements[stageId];if(judgement.recordStatus==="incomplete")incompletePackStages.push({packId:pack.packId,stageId,missingFields:judgement.missingFields,sourceFieldsPresent:judgement.sourceFieldsPresent});}
 const primaryStageNodeCounts=Object.fromEntries(primaryIds.map(stageId=>[stageId,nodeMappings.filter(item=>item.curriculum.primaryStages.includes(stageId)).length])),evidenceLevelCounts={},stageRoleCounts={};for(const item of nodeMappings){const level=item.curriculum.evidenceLevel;evidenceLevelCounts[level]=(evidenceLevelCounts[level]??0)+1;for(const [stageId,role] of Object.entries(item.curriculum.roles)){const key=stageId+":"+role;stageRoleCounts[key]=(stageRoleCounts[key]??0)+1;}}
 const counts={atlasNodeCount:atlasNodes.length,domainKnowledgeNodeCount:nodeMappings.length,mathThinkingNodeCount:thinkingIds.length,packCount:packRecords.length,packStagePositionCount:packRecords.length*primaryIds.length,completePackStagePositionCount:packRecords.length*primaryIds.length-incompletePackStages.length,incompletePackStagePositionCount:incompletePackStages.length,primaryStageNodeCounts,multiStageNodeCount:nodeMappings.filter(item=>item.curriculum.sourceStages.length>1).length,beyondPrimaryNodeCount:nodeMappings.filter(item=>item.curriculum.beyondPrimary!==null).length,evidenceLevelCounts,stageRoleCounts,notCoveredNodeCount:actualNotCoveredIds.length,researchGapCount:researchGapIds.length,researchGapDomainNodeCount,researchGapThinkingNodeCount,adjacentMainRiskCount:adjacentMainIds.length,originalRelationshipCount:atlasEdges.length};
