export function assertGradeProgressionRuntimeData(model){assert(model&&model.schemaVersion===1,"Unsupported grade progression data schema");assert(sameSet(model.primaryStageIds??[],primaryStageIds),"Runtime model must expose exactly three primary stages");assert(sameSet(model.stages?.map(stage=>stage.id)??[],primaryStageIds),"Runtime stage definitions are incomplete");assert(Array.isArray(model.nodeMappings)&&model.nodeMappings.length===model.counts?.domainKnowledgeNodeCount,"Runtime node mappings do not match declared count");assert(Array.isArray(model.packs)&&model.packs.length===model.counts?.packCount,"Runtime pack records do not match declared count");return model;}

export async function loadGradeProgressionData(options={}){const url=options.url??"./data/grade-progression.json",fetcher=options.fetcher??globalThis.fetch;assert(typeof fetcher==="function","A fetch implementation is required to load grade progression data");const response=await fetcher(url);assert(response&&response.ok,"Unable to load grade progression data"+(response?.status?": "+response.status:""));return assertGradeProgressionRuntimeData(await response.json());}